    /// <summary>Row of design/hooks.json. Every place the mod touches Risk of Rain 2 (RoR2.dll, 2026-10 build, decompiled with ilspycmd for reference only). method = 'event' subscribes to a public RoR2 ...</summary>
    public sealed class HookRow
    {
        public string Id;
        public string Method;
        public string Target;
        public string Purpose;
        public string Reads;
        public string Side;

        public static readonly HookRow[] All = new HookRow[]
        {
            new HookRow { Id = "content_pack", Method = "event", Target = "RoR2.ContentManagement.ContentManager.collectContentPackProviders", Purpose = "register body prefabs, survivor defs, skill defs/families, entity state types and buff defs (one IContentPackProvider; loads the Deadlock cache during the loading screen)", Reads = "heroes.*, stats.*, skills.*, buffs.*", Side = "both" },
            new HookRow { Id = "language", Method = "harmony-prefix", Target = "RoR2.Language.GetLocalizedStringByToken(string)", Purpose = "answer DLR_* tokens (names, subtitles, lore, skill names/descriptions, buff names) in every language", Reads = "heroes.displayName/subtitle/lore, skills.name/description, buffs.name", Side = "client" },
            new HookRow { Id = "stats_recalc", Method = "harmony-postfix", Target = "RoR2.CharacterBody.RecalculateStats()", Purpose = "apply our buffs' move speed / attack speed / armor / regen / damage (damageAdd: Pocket's Barrage amp) and slow resistance (vanilla level scaling of base stats is untouched and comes from the level* fields)", Reads = "buffs.moveSpeedAdd/attackSpeedAdd/armorAdd/regenAdd/slowResist, buffs.linearSlow, buffs.bossStatCut, buffs.accelerationAdd, buffs.jumpPowerAdd, buffs.jumpCountAdd, buffs.damageAdd", Side = "both" },
            new HookRow { Id = "damage_mods", Method = "harmony-prefix", Target = "RoR2.HealthComponent.TakeDamage(RoR2.DamageInfo)", Purpose = "Fixation and Napalm damage amp from their owner, Bullet Dance evasion; markCrit buffs (Wraith's crit card mark): the next real hit on the marked body is a certain crit and uses the mark up", Reads = "buffs.damageTakenFromOwnerPerStack/evasionChance", Side = "server" },
            new HookRow { Id = "model", Method = "component", Target = "DeadlockOfRain.ModelBuilder.Build (a model GameObject built per hero from the cache)", Purpose = "skeleton + one SkinnedMeshRenderer per material + legacy Animation clips from the player's Deadlock install, attached to the body's ModelLocator with CharacterModel/HurtBoxGroup/ChildLocator", Reads = "heroes.heightScale/widthScale/meshInclude, animations.*", Side = "client" },
            new HookRow { Id = "locomotion", Method = "component", Target = "DeadlockOfRain.DeadlockAnimator", Purpose = "pick idle/run/sprint/jump/land clips from CharacterMotor + InputBank each frame, layer gestures (reload/abilities) on the upper body; gun rig: hold the gun arms in aimPose, weld the gun to its hand, turn the chest so the gun points at the camera aim, recoil on shots", Reads = "animations.*", Side = "client" },
            new HookRow { Id = "audio", Method = "component", Target = "DeadlockOfRain.DeadlockAudio (winmm waveOut mixer)", Purpose = "play the hero's Deadlock sounds (decoded WAVs in the cache) at volume_master * volume_sfx, with distance falloff from the camera", Reads = "sounds.*", Side = "client" },
            new HookRow { Id = "test_mode", Method = "component", Target = "DeadlockOfRain.MeltyTest", Purpose = "Melty test.checks: while %LOCALAPPDATA%/Melty/test/deadlock-of-rain.json exists, start a run, play each hero, measure every skill's effect against skills.expect, check the gun rig, the 4 skill slots plus the starting ult equipment, level stats and scale, and append pass/fail lines to the checks file", Reads = "skills.*, stats.*, heroes.*", Side = "both" },
            new HookRow { Id = "loadout_skins", Method = "harmony-postfix", Target = "RoR2.UI.LoadoutPanelController+Row.FromSkin (public static on a private nested class)", Purpose = "give our heroes' empty skins row one 'Default' button, so the loadout panel's gamepad navigation does not index an empty row", Reads = "heroes.imageSmall/primaryColor", Side = "client" },
            new HookRow { Id = "missing_hero_lock", Method = "harmony-prefix", Target = "RoR2.UserProfile.HasSurvivorUnlocked", Purpose = "a released hero that could not be read from the player's Deadlock keeps a placeholder survivor (Content/MissingHeroes.cs); nobody ever has it unlocked, so it can never be picked", Reads = "heroes.displayName/sortPosition", Side = "client" },
            new HookRow { Id = "missing_hero_tile", Method = "harmony-postfix", Target = "RoR2.UI.SurvivorIconController.Rebuild (private)", Purpose = "the placeholder tile keeps its red ! (locked tiles are drawn black) and its hover names the hero, the reason and both version pairs (built with / this PC)", Reads = "heroes.displayName", Side = "client" },
