            new HookRow { Id = "heal_back", Method = "event", Target = "RoR2.GlobalEventManager.onServerDamageDealt", Purpose = "a hero with damageHealBack heals back that fraction of each hit taken over damageHealBackTime (Infernal Resilience)", Reads = "heroes.damageHealBack/damageHealBackTime", Side = "server" },
            new HookRow { Id = "stack_triggers", Method = "component", Target = "DeadlockOfRain.Buffs.Stack (called from our guns and projectiles)", Purpose = "add stacking debuffs (crits add critStacks) and fire their trigger at triggerStacks: Fixation burst, Static discharge, Afterburn ignition; the flash and arcs reach every player through the relay effect", Reads = "buffs.critStacks/trigger*/withBuff", Side = "server" },
