            new HookRow { Id = "equipment_defs", Method = "event", Target = "RoR2.ContentManagement.ContentManager.collectContentPackProviders (ContentPack.equipmentDefs)", Purpose = "register one EquipmentDef per equipment row (cooldown, drop rules, icon, a small hero figure as the pickup model); RoR2 puts canDrop equipment into the chest pools itself", Reads = "equipment.*, skills(slot=equipment).cooldown/icon/name/description", Side = "both" },
